    flash: {"q":"Combien de grands crus et de premiers crus compte Gevrey-Chambertin, et quelle couleur y produit-on ?","a":"9 grands crus et 26 premiers crus ; uniquement du rouge (pinot noir).","keys":[["9","neuf"],["26"],["rouge"]]},
